import {chromium} from '@playwright/test';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
const file='.forgewright/runtime/fw-argon-refactor-20261109/rf01-live-current-workspace/drawer-motion.html';
const bytes=readFileSync(file);
const browser=await chromium.launch({headless:true,channel:'chrome'});
const out={artifact:file,sha256:createHash('sha256').update(bytes).digest('hex')};
try{
 const context=await browser.newContext({viewport:{width:390,height:844},hasTouch:true,isMobile:true});
 await context.route('**/*',route=>route.abort());
 const page=await context.newPage();
 await page.setContent(bytes.toString('utf8'),{waitUntil:'domcontentloaded'});
 const toggle=page.locator('#drawer-toggle');
 await toggle.tap({timeout:3000});
 out.openedByTouch=await toggle.getAttribute('aria-expanded');
 await page.waitForTimeout(250);
 out.occlusion=await toggle.evaluate(el=>{const r=el.getBoundingClientRect();const hit=document.elementFromPoint(r.x+r.width/2,r.y+r.height/2);return {hitId:hit?.id,hitTag:hit?.tagName,drawerCoversToggle:document.getElementById('inspector-drawer').contains(hit)}});
 try{await toggle.tap({timeout:1500});out.closeTap='succeeded'}catch(e){out.closeTap=e.name;}
 out.openAfterCloseAttempt=await toggle.getAttribute('aria-expanded');
 out.buttonsInsideDrawer=await page.locator('#inspector-drawer button').count();
 await page.keyboard.press('Escape');
 out.escapeCloses=(await toggle.getAttribute('aria-expanded'))==='false';
 await page.emulateMedia({reducedMotion:'reduce'});
 out.reducedMotionDuration=await page.locator('#inspector-drawer').evaluate(el=>getComputedStyle(el).transitionDuration);
 await context.close();
}finally{await browser.close();}
console.log(JSON.stringify(out));

